import htsjdk.samtools.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Extract {
  static String REFS;
  static class Cand {
    String chrom,id,ref,alt; int pos;
    boolean isDel(){return ref.length()>alt.length();}
    int delLen(){return ref.length()-alt.length();}
    boolean isSnv(){return ref.length()==1&&alt.length()==1;}
  }
  static boolean gapEquiv(int g0oneBased,int len,Cand c){
    int w=30, L=REFS.length();
    int cs0=c.pos;
    String candS=REFS.substring(Math.max(0,cs0-w),cs0)+REFS.substring(cs0+c.delLen(),Math.min(L,cs0+c.delLen()+w));
    int g0=g0oneBased-1;
    String readS=REFS.substring(Math.max(0,g0-w),g0)+REFS.substring(g0+len,Math.min(L,g0+len+w));
    return candS.equals(readS);
  }
  static int supports(SAMRecord r,Cand c){
    if(c.isSnv()){
      int rp=r.getReadPositionAtReferencePosition(c.pos);
      if(rp<=0) return -1;
      byte[] b=r.getReadBases();
      if(rp-1>=b.length) return -1;
      char rb=(char)Character.toUpperCase(b[rp-1]);
      return rb==c.alt.charAt(0)? rp-1 : -1;
    } else if(c.isDel()){
      int refPos=r.getAlignmentStart(); int readPos=0;
      for(CigarElement ce: r.getCigar().getCigarElements()){
        CigarOperator op=ce.getOperator(); int len=ce.getLength();
        if(op==CigarOperator.D){
          if(len==c.delLen() && gapEquiv(refPos,len,c)) return readPos;
          refPos+=len;
        } else if(op.consumesReferenceBases()&&op.consumesReadBases()){refPos+=len;readPos+=len;}
        else if(op.consumesReferenceBases()){refPos+=len;}
        else if(op.consumesReadBases()){readPos+=len;}
      }
      return -1;
    }
    return -1;
  }
  static int mismatches(SAMRecord r,Cand c){
    int mm=0; int refPos=r.getAlignmentStart(); int readPos=0;
    byte[] b=r.getReadBases();
    for(CigarElement ce: r.getCigar().getCigarElements()){
      CigarOperator op=ce.getOperator(); int len=ce.getLength();
      if(op==CigarOperator.M||op==CigarOperator.EQ||op==CigarOperator.X){
        for(int k=0;k<len;k++){
          int ri=readPos+k, fi=refPos-1+k;
          if(ri>=b.length||fi<0||fi>=REFS.length()) continue;
          char rb=(char)Character.toUpperCase(b[ri]); char fb=(char)Character.toUpperCase(REFS.charAt(fi));
          if(rb!=fb&&rb!='N'){
            int refp=refPos+k;
            if(c.isSnv()&&refp==c.pos) continue;
            mm++;
          }
        }
        refPos+=len; readPos+=len;
      } else if(op==CigarOperator.D||op==CigarOperator.N){refPos+=len;}
      else if(op==CigarOperator.I||op==CigarOperator.S){readPos+=len;}
    }
    return mm;
  }
  public static void main(String[] args) throws Exception {
    List<Cand> cands=new ArrayList<>();
    for(String line: Files.readAllLines(Path.of("/task/input/candidates.vcf"))){
      if(line.startsWith("#")||line.isBlank()) continue;
      String[] f=line.split("\t");
      Cand c=new Cand(); c.chrom=f[0]; c.pos=Integer.parseInt(f[1]); c.id=f[2]; c.ref=f[3]; c.alt=f[4];
      cands.add(c);
    }
    StringBuilder sb=new StringBuilder();
    for(String line: Files.readAllLines(Path.of("/task/input/reference/ref.fa")))
      if(!line.startsWith(">")) sb.append(line.trim());
    REFS=sb.toString();
    int n=cands.size();
    @SuppressWarnings("unchecked")
    Map<String,List<SAMRecord>>[][] data=new Map[n][2];
    for(int i=0;i<n;i++) for(int s=0;s<2;s++) data[i][s]=new LinkedHashMap<>();
    SamReaderFactory fac=SamReaderFactory.makeDefault().referenceSequence(new File("/task/input/reference/ref.fa"));
    String[] bams={"/task/input/cram/tumor.cram","/task/input/cram/normal.cram"};
    for(int s=0;s<2;s++){
      try(SamReader reader=fac.open(new File(bams[s]))){
        long cnt=0;
        for(SAMRecord r: reader){
          cnt++;
          if(r.getReadUnmappedFlag()||r.getNotPrimaryAlignmentFlag()||r.getSupplementaryAlignmentFlag()||r.getDuplicateReadFlag()) continue;
          int st=r.getAlignmentStart(), en=r.getAlignmentEnd();
          if(st<=0||en<=0) continue;
          for(int i=0;i<n;i++){
            Cand c=cands.get(i);
            int cend=c.pos+(c.isDel()?c.delLen():0);
            if(st<=c.pos&&en>=cend)
              data[i][s].computeIfAbsent(r.getReadName(),k->new ArrayList<>()).add(r);
          }
        }
        System.err.println(bams[s]+" totalReads="+cnt);
      }
    }
    PrintWriter out=new PrintWriter(new FileWriter("/tmp/rev/review.tsv"));
    PrintWriter met=new PrintWriter(new FileWriter("/tmp/rev/metrics.txt"));
    out.println("variant_id\tcall\ttag\ttumor_alt\ttumor_depth\ttumor_vaf\tnormal_alt\tnormal_depth");
    String[] tags=new String[n];
    List<Set<String>> altSets=new ArrayList<>();
    int[][] altD=new int[n][2]; int[][] depD=new int[n][2];
    for(int i=0;i<n;i++){
      Cand c=cands.get(i);
      int[] alt=new int[2]; int[] dep=new int[2];
      Set<String> altMol=new HashSet<>();
      Map<String,List<SAMRecord>> supMol=new LinkedHashMap<>();
      for(int s=0;s<2;s++){
        dep[s]=data[i][s].size();
        for(Map.Entry<String,List<SAMRecord>> e: data[i][s].entrySet()){
          boolean sup=false;
          for(SAMRecord r: e.getValue()) if(supports(r,c)>=0){sup=true;break;}
          if(sup){alt[s]++; if(s==0){altMol.add(e.getKey()); supMol.put(e.getKey(),e.getValue());}}
        }
      }
      altSets.add(altMol); altD[i]=alt; depD[i]=dep;
      List<SAMRecord> supReads=new ArrayList<>();
      for(Map.Entry<String,List<SAMRecord>> e: supMol.entrySet()) supReads.addAll(e.getValue());
      int nSR=supReads.size(), nSM=supMol.size();
      int covF=0,covR=0;
      for(Map.Entry<String,List<SAMRecord>> e: data[i][0].entrySet()) for(SAMRecord r: e.getValue()){ if(r.getReadNegativeStrandFlag())covR++;else covF++; }
      int lowBQmol=0, lowMQmol=0, discMol=0;
      for(Map.Entry<String,List<SAMRecord>> e: supMol.entrySet()){
        int bestBQ=-1,bestMQ=-1,maxTL=0; boolean hasAltBase=false;
        for(SAMRecord r: e.getValue()){
          bestMQ=Math.max(bestMQ,r.getMappingQuality());
          maxTL=Math.max(maxTL,Math.abs(r.getInferredInsertSize()));
          int sp=supports(r,c);
          if(sp>=0&&c.isSnv()){
            byte[] q=r.getBaseQualities();
            if(q!=null&&sp<q.length){hasAltBase=true; bestBQ=Math.max(bestBQ,q[sp]);}
          }
        }
        if(c.isSnv()&&hasAltBase&&bestBQ<20) lowBQmol++;
        if(bestMQ<20) lowMQmol++;
        if(maxTL>1000) discMol++;
      }
      double mmSum=0; int sF=0,sR=0,endLo=0;
      List<Integer> dmins=new ArrayList<>();
      for(SAMRecord r: supReads){
        mmSum+=mismatches(r,c);
        if(r.getReadNegativeStrandFlag())sR++;else sF++;
        int sp=supports(r,c);
        int rl=r.getReadLength();
        int dmin=(sp>=0)?Math.min(sp,rl-1-sp):999;
        dmins.add(dmin);
        if(dmin<5) endLo++;
      }
      double bqFrac=nSM==0?0:(double)lowBQmol/nSM;
      double mqFrac=nSM==0?0:(double)lowMQmol/nSM;
      double avgMM=nSR==0?0:mmSum/nSR;
      double strandFrac=nSR==0?0:(double)Math.max(sF,sR)/nSR;
      boolean covBoth=covF>0&&covR>0;
      double endFrac=nSR==0?0:(double)endLo/nSR;
      double discFrac=nSM==0?0:(double)discMol/nSM;
      String tag=null;
      if(alt[1]>=2&&dep[1]>0&&(double)alt[1]/dep[1]>=0.05) tag="GERMLINE";
      else if(alt[0]<4) tag="LOW_SUPPORT";
      else if(c.isSnv()&&bqFrac>=0.75) tag="LOW_BASE_QUALITY";
      else if(mqFrac>=0.75) tag="LOW_MAPPING_QUALITY";
      else if(avgMM>=4.0) tag="MULTI_MISMATCH";
      else if(covBoth&&strandFrac>=0.90) tag="STRAND_BIAS";
      else if(endFrac>=0.75) tag="READ_END";
      else if(discFrac>=0.75) tag="DISCORDANT_PAIRS";
      tags[i]=tag;
      Collections.sort(dmins);
      met.printf(Locale.US,"%s %s>%s@%d alt=%d/%d N=%d/%d bq=%d/%d mq=%d/%d avgMM=%.2f str=%d/%d cov=%d/%d end=%d/%d disc=%d/%d tag=%s dmins=%s%n",
        c.id,c.ref,c.alt,c.pos,alt[0],dep[0],alt[1],dep[1],lowBQmol,nSM,lowMQmol,nSM,avgMM,Math.max(sF,sR),nSR,covF,covR,endLo,nSR,discMol,nSM,tag,dmins.toString());
    }
    for(int i=0;i+1<n;i++){
      Cand a=cands.get(i), b=cands.get(i+1);
      if(b.pos==a.pos+1&&a.isSnv()&&b.isSnv()&&tags[i]==null&&tags[i+1]==null){
        Set<String> u=new HashSet<>(altSets.get(i)); u.addAll(altSets.get(i+1));
        Set<String> in=new HashSet<>(altSets.get(i)); in.retainAll(altSets.get(i+1));
        double frac=u.isEmpty()?0:(double)in.size()/u.size();
        met.printf(Locale.US,"MNV %s/%s shared=%d/%d frac=%.3f%n",a.id,b.id,in.size(),u.size(),frac);
        if(frac>=0.90) tags[i+1]="MNV_PARTNER";
      }
    }
    for(int i=0;i<n;i++){
      Cand c=cands.get(i);
      String tag=tags[i];
      String call=tag==null?"somatic":"fail";
      String tagOut=tag==null?"PASS":tag;
      double vaf=depD[i][0]==0?0:(double)altD[i][0]/depD[i][0];
      out.printf(Locale.US,"%s\t%s\t%s\t%d\t%d\t%.6f\t%d\t%d%n",c.id,call,tagOut,altD[i][0],depD[i][0],vaf,altD[i][1],depD[i][1]);
    }
    out.close(); met.close();
    System.err.println("done");
  }
}
